SELECT ws.ws_order_number, ws.ws_sold_time_sk, td.t_hour, hd.hd_vehicle_count, hd.hd_income_band_sk, CASE WHEN hd.hd_vehicle_count = 0 THEN 'NoVehicleLowIncome' WHEN hd.hd_vehicle_count >= 2 AND hd.hd_income_band_sk >= 5 THEN 'HighVehicleHighIncome' ELSE 'Other' END AS customer_segment, ws.ws_net_profit, ws.ws_net_paid_inc_tax, CASE WHEN ws.ws_net_paid_inc_tax = 0 THEN NULL ELSE (ws.ws_net_profit / ws.ws_net_paid_inc_tax) * 100 END AS profit_margin_pct, (SELECT SUM(ss.ss_quantity) FROM store_sales ss WHERE ss.ss_sold_time_sk = ws.ws_sold_time_sk) AS store_quantity_at_same_time, ROW_NUMBER() OVER (PARTITION BY CASE WHEN hd.hd_vehicle_count = 0 THEN 'NoVehicleLowIncome' WHEN hd.hd_vehicle_count >= 2 AND hd.hd_income_band_sk >= 5 THEN 'HighVehicleHighIncome' ELSE 'Other' END ORDER BY ws.ws_net_profit DESC) AS rn_per_segment FROM web_sales ws JOIN time_dim td ON ws.ws_sold_time_sk = td.t_time_sk JOIN household_demographics hd ON ws.ws_bill_hdemo_sk = hd.hd_demo_sk WHERE ws.ws_net_paid_inc_tax IS NOT NULL
